          "id": "code-ml-21-2-ch21_2_scratch",
          "title": "First-Principles NumPy: K-Medoids PAM (BUILD + SWAP) vs K-Means pada Kontaminasi 3.2% Outlier",
          "language": "python",
          "filename": "21_2_pam_kmedoids_scratch.py",
          "code": "import numpy as np\n\ndef pam_kmedoids(D: np.ndarray, k: int, max_iter: int = 50):\n    \"\"\"Implementasi eksak PAM (Partitioning Around Medoids: fase BUILD + SWAP) atas matriks jarak D.\"\"\"\n    n = D.shape[0]\n    # Fase BUILD: pilih medoid pertama dengan total jarak terkecil, lalu sisanya secara serakah\n    medoids = [int(np.argmin(D.sum(axis=1)))]\n    best_dist = D[:, medoids[0]].copy()\n    for _ in range(1, k):\n        gains = np.maximum(best_dist[:, None] - D, 0.0).sum(axis=0)\n        gains[medoids] = -1.0\n        next_m = int(np.argmax(gains))\n        medoids.append(next_m)\n        best_dist = np.minimum(best_dist, D[:, next_m])\n\n    medoids = np.array(medoids, dtype=int)\n    init_cost = float(np.sum(np.min(D[:, medoids], axis=1)))\n    curr_cost = init_cost\n    n_swaps = 0\n\n    # Fase SWAP: uji penggantian (medoid, non-medoid) terbaik sampai konvergen ke minimum lokal\n    for _ in range(max_iter):\n        is_med = np.zeros(n, dtype=bool)\n        is_med[medoids] = True\n        non_meds = np.where(~is_med)[0]\n\n        best_cand_cost = curr_cost\n        best_pair = None\n        for pos in range(k):\n            other = np.delete(medoids, pos)\n            d_other = np.min(D[:, other], axis=1) if k > 1 else np.full(n, np.inf)\n            # Biaya total baru untuk seluruh kandidat non-medoid sekaligus (vektorisasi)\n            cand_costs = np.minimum(d_other[:, None], D[:, non_meds]).sum(axis=0)\n            min_idx = int(np.argmin(cand_costs))\n            if cand_costs[min_idx] < best_cand_cost - 1e-9:\n                best_cand_cost = float(cand_costs[min_idx])\n                best_pair = (pos, int(non_meds[min_idx]))\n\n        if best_pair is None:\n            break\n        medoids[best_pair[0]] = best_pair[1]\n        curr_cost = best_cand_cost\n        n_swaps += 1\n\n    labels = np.argmin(D[:, medoids], axis=1)\n    return np.sort(medoids), labels, init_cost, curr_cost, n_swaps\n\n# Uji ketahanan terhadap 3% outlier tersebar (~40 unit): K-Means (L2^2 Mean) vs K-Medoids PAM (L1 Manhattan)\nrng = np.random.default_rng(221)\ntrue_centers = np.array([[0.0, 0.0], [10.0, 0.0], [5.0, 8.8]])\nX_clean = np.vstack([rng.normal(mu, 0.65, size=(65, 2)) for mu in true_centers])\n\n# Tambahkan 6 titik outlier ekstrem menyebar di segala arah (3.0% kontaminasi)\nX_outliers = np.array([[48.0, 42.0], [-42.0, 38.0], [44.0, -36.0], [-38.0, -40.0], [5.0, 52.0], [46.0, 39.0]])\nX_dirty = np.vstack([X_clean, X_outliers])\n\n# 1) K-Means L2 dari nol (inisialisasi realistis via K-Means++ agar mencerminkan produksi!)\ndef init_pp(X_in, k, r):\n    c = [X_in[int(r.integers(0, len(X_in)))]]\n    for _ in range(1, k):\n        d2 = np.min(np.sum((X_in[:, None, :] - np.array(c)[None, :, :]) ** 2, axis=2), axis=1)\n        c.append(X_in[int(r.choice(len(X_in), p=d2 / np.sum(d2)))])\n    return np.array(c, dtype=float)\n\nC_km = init_pp(X_dirty, 3, np.random.default_rng(221))\nfor _ in range(40):\n    d2 = np.sum((X_dirty[:, None, :] - C_km[None, :, :]) ** 2, axis=2)\n    lbl_km = np.argmin(d2, axis=1)\n    for j in range(3):\n        if np.any(lbl_km == j):\n            C_km[j] = X_dirty[lbl_km == j].mean(axis=0)\n\n# 2) K-Medoids PAM atas matriks jarak Manhattan L1\nD_l1 = np.sum(np.abs(X_dirty[:, None, :] - X_dirty[None, :, :]), axis=2)\nmed_idx, lbl_pam, c_init, c_final, swaps = pam_kmedoids(D_l1, k=3)\nC_pam = X_dirty[med_idx]\n\ndef mean_center_drift(est_centers: np.ndarray, gt_centers: np.ndarray) -> float:\n    \"\"\"Rata-rata jarak Euclidean dari tiap pusat sejati ke pusat estimasi terdekat.\"\"\"\n    dists = np.linalg.norm(gt_centers[:, None, :] - est_centers[None, :, :], axis=2)\n    return float(np.mean(np.min(dists, axis=1)))\n\nprint(\"=== Ketahanan Pusat Klaster Terhadap 3.0% Outlier Menyebar (~45 unit) ===\")\nprint(f\"PAM BUILD Cost = {c_init:.2f} -> SWAP Final Cost = {c_final:.2f} (swaps={swaps}, semua medoid adalah titik riil!)\")\nprint(f\"Pergeseran Rata-Rata Pusat dari Ground-Truth | K-Means (Mean L2^2)  = {mean_center_drift(C_km, true_centers):8.4f}\")\nprint(f\"Pergeseran Rata-Rata Pusat dari Ground-Truth | K-Medoids (PAM L1)   = {mean_center_drift(C_pam, true_centers):8.4f}\")\nprint(f\"Ukuran Klaster K-Means  (terdistorsi outlier L2^2!)    : {sorted(np.bincount(lbl_km, minlength=3).tolist())}\")\nprint(f\"Ukuran Klaster PAM (L1) (3 klaster sejati ~65+ utuh!)  : {sorted(np.bincount(lbl_pam, minlength=3).tolist())}\")",
          "expectedOutput": "=== Ketahanan Pusat Klaster Terhadap 3.0% Outlier Menyebar (~45 unit) ===\nPAM BUILD Cost = 668.68 -> SWAP Final Cost = 615.22 (swaps=1, semua medoid adalah titik riil!)\nPergeseran Rata-Rata Pusat dari Ground-Truth | K-Means (Mean L2^2)  =   3.6737\nPergeseran Rata-Rata Pusat dari Ground-Truth | K-Medoids (PAM L1)   =   0.2642\nUkuran Klaster K-Means  (terdistorsi outlier L2^2!)    : [3, 66, 132]\nUkuran Klaster PAM (L1) (3 klaster sejati ~65+ utuh!)  : [66, 66, 69]",
          "actualOutput": "=== Ketahanan Pusat Klaster Terhadap 3.0% Outlier Menyebar (~45 unit) ===\nPAM BUILD Cost = 668.68 -> SWAP Final Cost = 615.22 (swaps=1, semua medoid adalah titik riil!)\nPergeseran Rata-Rata Pusat dari Ground-Truth | K-Means (Mean L2^2)  =   3.6737\nPergeseran Rata-Rata Pusat dari Ground-Truth | K-Medoids (PAM L1)   =   0.2642\nUkuran Klaster K-Means  (terdistorsi outlier L2^2!)    : [3, 66, 132]\nUkuran Klaster PAM (L1) (3 klaster sejati ~65+ utuh!)  : [66, 66, 69]",
