          "code": "import numpy as np\nfrom sklearn.cluster import BisectingKMeans, KMeans, MiniBatchKMeans\nfrom sklearn.datasets import make_blobs\nfrom sklearn.metrics import adjusted_rand_score\nfrom sklearn.preprocessing import StandardScaler\n\n# Dataset 1600 sampel x 20 fitur dengan 8 klaster (termasuk variasi ukuran klaster)\ncluster_sizes = [320, 280, 240, 220, 190, 160, 140, 50]  # Klaster ke-7 adalah segmen minoritas 3.1%!\nX, y_true = make_blobs(\n    n_samples=cluster_sizes,\n    n_features=20,\n    centers=None,\n    cluster_std=1.35,\n    center_box=(-9.0, 9.0),\n    random_state=42,\n)\nXs = StandardScaler().fit_transform(X)\n\nmodels = [\n    (\"KMeans (Lloyd Exact, k-means++)\", KMeans(n_clusters=8, init=\"k-means++\", n_init=10, random_state=42)),\n    (\"MiniBatchKMeans (b=64, default)\", MiniBatchKMeans(n_clusters=8, batch_size=64, n_init=5, random_state=42)),\n    (\"MiniBatchKMeans (b=512, rr=0.005)\", MiniBatchKMeans(n_clusters=8, batch_size=512, reassignment_ratio=0.005, n_init=5, random_state=42)),\n    (\"BisectingKMeans (biggest_inertia)\", BisectingKMeans(n_clusters=8, init=\"k-means++\", bisecting_strategy=\"biggest_inertia\", n_init=5, random_state=42)),\n    (\"BisectingKMeans (largest_cluster)\", BisectingKMeans(n_clusters=8, init=\"k-means++\", bisecting_strategy=\"largest_cluster\", n_init=5, random_state=42)),\n]\n\nexact_inertia = None\nprint(\"=== Benchmark Skalabilitas & Kualitas Klaster (N=1600, d=20, K=8, 1 Segmen Minoritas 3.1%) ===\")\nprint(\"Metode                            |   Inertia  | +Gap% vs Exact |  ARI   | Min Klaster Size\")\nprint(\"-\" * 92)\nfor name, model in models:\n    model.fit(Xs)\n    if exact_inertia is None:\n        exact_inertia = float(model.inertia_)\n    gap_pct = 100.0 * (float(model.inertia_) - exact_inertia) / exact_inertia\n    ari = adjusted_rand_score(y_true, model.labels_)\n    min_sz = int(np.min(np.bincount(model.labels_, minlength=8)))\n    print(f\"{name:33s} | {model.inertia_:10.2f} | {gap_pct:+13.2f}% | {ari:6.4f} | {min_sz:4d} (sejati=50)\")",
          "expectedOutput": "=== Benchmark Skalabilitas & Kualitas Klaster (N=1600, d=20, K=8, 1 Segmen Minoritas 3.1%) ===\nMetode                            |   Inertia  | +Gap% vs Exact |  ARI   | Min Klaster Size\n--------------------------------------------------------------------------------------------\nKMeans (Lloyd Exact, k-means++)   |    2458.93 |         +0.00% | 1.0000 |   50 (sejati=50)\nMiniBatchKMeans (b=64, default)   |    2464.21 |         +0.21% | 1.0000 |   50 (sejati=50)\nMiniBatchKMeans (b=512, rr=0.005) |    2461.07 |         +0.09% | 1.0000 |   50 (sejati=50)\nBisectingKMeans (biggest_inertia) |    2458.93 |         -0.00% | 1.0000 |   50 (sejati=50)\nBisectingKMeans (largest_cluster) |    3062.20 |        +24.53% | 0.8950 |  132 (sejati=50)",
