          "code": "import numpy as np\nfrom sklearn.cluster import KMeans, SpectralClustering\nfrom sklearn.datasets import make_circles, make_moons\nfrom sklearn.metrics import adjusted_rand_score\nfrom sklearn.preprocessing import StandardScaler\n\nX_moons, y_moons = make_moons(n_samples=260, noise=0.065, random_state=42)\nX_circ, y_circ = make_circles(n_samples=260, factor=0.48, noise=0.05, random_state=42)\n\n# Benchmark sensitivitas parameter affinity (RBF gamma terlalu kecil vs tepat vs terlalu besar) vs k-NN!\nX_m = StandardScaler().fit_transform(X_moons)\nX_c = StandardScaler().fit_transform(X_circ)\n\nconfigs = [\n    (\"KMeans++ Baseline\", lambda X: KMeans(n_clusters=2, n_init=10, random_state=42).fit_predict(X)),\n    (\"Spectral RBF (gamma=0.2, terlalu lebar)\", lambda X: SpectralClustering(n_clusters=2, affinity=\"rbf\", gamma=0.2, random_state=42).fit_predict(X)),\n    (\"Spectral RBF (gamma=8.0, pas)\", lambda X: SpectralClustering(n_clusters=2, affinity=\"rbf\", gamma=8.0, random_state=42).fit_predict(X)),\n    (\"Spectral RBF (gamma=120.0, terputus)\", lambda X: SpectralClustering(n_clusters=2, affinity=\"rbf\", gamma=120.0, random_state=42).fit_predict(X)),\n    (\"Spectral k-NN (k=12, assign='kmeans')\", lambda X: SpectralClustering(n_clusters=2, affinity=\"nearest_neighbors\", n_neighbors=12, assign_labels=\"kmeans\", random_state=42).fit_predict(X)),\n    (\"Spectral k-NN (k=12, assign='cluster_qr')\", lambda X: SpectralClustering(n_clusters=2, affinity=\"nearest_neighbors\", n_neighbors=12, assign_labels=\"cluster_qr\", random_state=42).fit_predict(X)),\n]\n\nprint(\"=== Scikit-Learn 1.9: Sensitivitas Affinity RBF Gamma vs k-NN & cluster_qr ===\")\nprint(\"Konfigurasi Model                         | ARI (Moons) | ARI (Circles)\")\nprint(\"-\" * 73)\nfor name, fn in configs:\n    ari_m = adjusted_rand_score(y_moons, fn(X_m))\n    ari_c = adjusted_rand_score(y_circ, fn(X_c))\n    print(f\"{name:41s} |   {ari_m:7.4f}   |    {ari_c:7.4f}\")",
          "expectedOutput": "=== Scikit-Learn 1.9: Sensitivitas Affinity RBF Gamma vs k-NN & cluster_qr ===\nKonfigurasi Model                         | ARI (Moons) | ARI (Circles)\n-------------------------------------------------------------------------\nKMeans++ Baseline                         |    0.4561   |    -0.0038\nSpectral RBF (gamma=0.2, terlalu lebar)   |    0.4666   |    -0.0038\nSpectral RBF (gamma=8.0, pas)             |    1.0000   |     1.0000\nSpectral RBF (gamma=120.0, terputus)      |    1.0000   |     1.0000\nSpectral k-NN (k=12, assign='kmeans')     |    1.0000   |     1.0000\nSpectral k-NN (k=12, assign='cluster_qr') |    1.0000   |     1.0000",
          "actualOutput": "=== Scikit-Learn 1.9: Sensitivitas Affinity RBF Gamma vs k-NN & cluster_qr ===\nKonfigurasi Model                         | ARI (Moons) | ARI (Circles)\n-------------------------------------------------------------------------\nKMeans++ Baseline                         |    0.4561   |    -0.0038\nSpectral RBF (gamma=0.2, terlalu lebar)   |    0.4666   |    -0.0038\nSpectral RBF (gamma=8.0, pas)             |    1.0000   |     1.0000\nSpectral RBF (gamma=120.0, terputus)      |    1.0000   |     1.0000\nSpectral k-NN (k=12, assign='kmeans')     |    1.0000   |     1.0000\nSpectral k-NN (k=12, assign='cluster_qr') |    1.0000   |     1.0000",
