          "language": "python",
          "filename": "21_4_validation_pitfalls_audit.py",
          "code": "import numpy as np\nfrom sklearn.cluster import KMeans, SpectralClustering\nfrom sklearn.datasets import make_circles\nfrom sklearn.metrics import adjusted_rand_score, silhouette_samples, silhouette_score\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(243)\n\n# 1) Jebakan Axis-Aligned vs PCA-Aligned Reference Box pada Gap Statistic (1 Elips Berkorelasi rho=0.93!)\nX_corr = rng.multivariate_normal([0.0, 0.0], [[4.0, 3.72], [3.72, 4.0]], size=240)\n\ndef gap_choose_k(X: np.ndarray, align_pca: bool, k_max: int = 4, n_refs: int = 10, seed: int = 42):\n    r = np.random.default_rng(seed)\n    mu = X.mean(axis=0, keepdims=True)\n    Xc = X - mu\n    _, _, Vt = np.linalg.svd(Xc, full_matrices=False)\n    Z = Xc @ Vt.T if align_pca else Xc\n    lo, hi = Z.min(axis=0), Z.max(axis=0)\n\n    def wcss(D, k, s):\n        if k == 1:\n            return float(np.sum((D - D.mean(axis=0)) ** 2))\n        return float(KMeans(n_clusters=k, init=\"k-means++\", n_init=5, random_state=s).fit(D).inertia_)\n\n    gaps, sks = [], []\n    for k in range(1, k_max + 1):\n        lw = np.log(wcss(X, k, seed + k))\n        refs = []\n        for b in range(n_refs):\n            U = r.uniform(lo, hi, size=X.shape)\n            Xr = (U @ Vt + mu) if align_pca else (U + mu)\n            refs.append(np.log(wcss(Xr, k, seed + 50 * b + k)))\n        gaps.append(float(np.mean(refs) - lw))\n        sks.append(float(np.std(refs, ddof=1) * np.sqrt(1.0 + 1.0 / n_refs)))\n    k_opt = k_max\n    for i in range(k_max - 1):\n        if gaps[i] >= gaps[i + 1] - sks[i + 1]:\n            k_opt = i + 1\n            break\n    return k_opt, [round(g, 3) for g in gaps]\n\nk_axis, g_axis = gap_choose_k(X_corr, align_pca=False)\nk_pca, g_pca = gap_choose_k(X_corr, align_pca=True)\nprint(\"=== 1. Jebakan Bounding Box pada 1 Elips Berkorelasi (K* Sejati = 1) ===\")\nprint(f\"Axis-Aligned Uniform Box | Gaps(1..4)={g_axis} -> K*={k_axis}  <-- Halusinasi klaster karena ruang kosong sudut!\")\nprint(f\"PCA-Aligned Uniform Box  | Gaps(1..4)={g_pca} -> K*={k_pca}  <-- Tepat mendeteksi K*=1!\")\n\n# 2) Bias Geometris Silhouette pada Struktur Non-Konveks (make_circles)\nX_c, y_c = make_circles(n_samples=300, factor=0.45, noise=0.05, random_state=42)\nX_cs = StandardScaler().fit_transform(X_c)\nlbl_km = KMeans(n_clusters=2, n_init=10, random_state=42).fit_predict(X_cs)\nlbl_sp = SpectralClustering(n_clusters=2, affinity=\"nearest_neighbors\", n_neighbors=12, random_state=42).fit_predict(X_cs)\n\nprint(\"\\n=== 2. Bias Sferis Silhouette pada Geometri Cincin Konsentris ===\")\nprint(f\"K-Means++ (Salah potong!) | ARI={adjusted_rand_score(y_c, lbl_km):.4f} | Silhouette={silhouette_score(X_cs, lbl_km):.4f}  <-- Menang palsu di Silhouette!\")\nprint(f\"Spectral k-NN (Sempurna!) | ARI={adjusted_rand_score(y_c, lbl_sp):.4f} | Silhouette={silhouette_score(X_cs, lbl_sp):.4f}  <-- Dihukum Silhouette Euclidean!\")\n\n# 3) Audit Per-Sample Silhouette: Mendeteksi Klaster \"Sampah\" Berskor Negatif Saat Over-Clustering (K=5 pada data K*=3)\nX_3 = np.vstack([\n    rng.normal([-3.5, 0.0], 0.7, size=(100, 2)),\n    rng.normal([ 3.5, 0.0], 0.7, size=(100, 2)),\n    rng.normal([ 0.0, 4.0], 0.7, size=(100, 2)),\n])\nlbl_over = KMeans(n_clusters=5, init=\"k-means++\", n_init=10, random_state=42).fit_predict(X_3)\nsil_each = silhouette_samples(X_3, lbl_over)\nprint(\"\\n=== 3. Per-Sample Silhouette Audit Saat Dipaksa Over-Clustering (K=5 pada 3 Klaster Sejati) ===\")\nfor c in range(5):\n    sc = sil_each[lbl_over == c]\n    neg_pct = 100.0 * float(np.mean(sc < 0.0))\n    print(f\"  Klaster {c} | n={len(sc):3d} | Mean Silh={np.mean(sc):+.3f} | Min={np.min(sc):+.3f} | Sampel Negatif={neg_pct:5.1f}%\")",
